export function testArgv(opts: { plan?: boolean; project?: string; year?: string; configuration?: string; filter?: string; attach?: boolean; id?: string; noBuild?: boolean; allowDeployedAddin?: boolean; unstick?: boolean; timeoutSeconds?: number; } = {}): string[] {
  const argv = ["test"];
  if (opts.plan) argv.push("--plan");
  option(argv, "--project", opts.project);
  option(argv, "--year", opts.year);
  option(argv, "--configuration", opts.configuration);
  option(argv, "--filter", opts.filter);
  if (opts.attach) argv.push("--attach");
  option(argv, "--id", opts.id);
  if (opts.noBuild) argv.push("--no-build");
  if (opts.allowDeployedAddin) argv.push("--allow-deployed-addin");
  if (opts.unstick) argv.push("--unstick");
  option(argv, "--timeout-seconds", opts.timeoutSeconds);
  argv.push("--json");
  return argv;
}

export function versionArgv(): string[] {
  const argv = ["version"];
  argv.push("--json");
  return argv;
}

function value(value: string | number | undefined, verb: string, name: string): string {
  const text = value == null ? "" : String(value).trim();
  if (!text) throw new Error(`${verb} requires ${name}`);
  return text;
}

function option(argv: string[], flag: string, value: string | number | undefined): void {
  if (value != null && String(value).trim()) argv.push(flag, String(value).trim());
}
